	function whereAmI(){
		var tz = null;
		try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone; } catch(e){}
		if(tz && TZ[tz]) return {lat: TZ[tz][0], lon: TZ[tz][1]};
